import sys
import xml.etree.ElementTree as ET
import json
import os

def parse_auth_config(file_path):
    tree = ET.parse(file_path)
    root = tree.getroot()
    users = {}
    for user_elem in root.findall('user'):
        name = user_elem.get('name')
        token_elem = user_elem.find('token')
        token = token_elem.text if token_elem is not None else None
        allow_actions = set()
        for allow_elem in user_elem.findall('allow'):
            action = allow_elem.get('action')
            if action:
                allow_actions.add(action)
        users[name] = {'token': token, 'actions': allow_actions}
    return users

def write_auth_cache(users, file_path):
    with open(file_path, 'w') as f:
        for name, data in users.items():
            f.write(f"{name}:{data['token']}:{':'.join(data['actions'])}")

def load_auth_cache(file_path):
    users = {}
    if os.path.exists(file_path):
        with open(file_path, 'r') as f:
            for line in f:
                name, token, actions = line.strip().split(':', 2)
                actions_set = set(actions.split(':')) if actions else set()
                users[name] = {'token': token, 'actions': actions_set}
    return users

def main():
    cache_file = 'auth.cache'
    xml_file = 'auth.xml'

    if os.path.exists(cache_file):
        users = load_auth_cache(cache_file)
    else:
        users = parse_auth_config(xml_file)
        write_auth_cache(users, cache_file)

    input_data = json.loads(sys.stdin.read())
    token = input_data.get('token')
    action = input_data.get('action')

    for name, data in users.items():
        if data['token'] == token and action in data['actions']:
            print(f"ok {name}")
            return
    print("denied")
    sys.exit(0)

if __name__ == "__main__":
    main()
